// The demo app generated by `cubby init` (cli/template/src/App.tsx).
export class TemplateAppPage {
  constructor(page) {
    this.page = page;
    this.email = page.getByLabel('Email');
    this.password = page.getByLabel('Password');
    this.switchToSignUp = page.getByRole('button', { name: /Need an account\?/ });
    this.createAccountButton = page.getByRole('button', { name: 'Create account' });
    this.logInButton = page.getByRole('button', { name: 'Log in', exact: true });
    this.newTask = page.getByLabel('New task');
    this.addButton = page.getByRole('button', { name: 'Add', exact: true });
    this.tasks = page.getByRole('list', { name: 'Tasks' });
    this.emptyState = this.tasks.getByText('No tasks yet');
    this.logOutButton = page.getByRole('button', { name: 'Log out' });
    this.error = page.getByRole('alert');
  }

  async goto(url) {
    await this.page.goto(url);
  }

  async signUp(email, password) {
    await this.switchToSignUp.click();
    await this.email.fill(email);
    await this.password.fill(password);
    await this.createAccountButton.click();
    await this.newTask.waitFor();
  }

  async logIn(email, password) {
    await this.email.fill(email);
    await this.password.fill(password);
    await this.logInButton.click();
    await this.newTask.waitFor();
  }

  task(title) {
    return {
      item: this.tasks.getByRole('listitem').filter({ hasText: title }),
      done: this.page.getByLabel(`Done: ${title}`),
      deleteButton: this.page.getByRole('button', { name: `Delete ${title}` }),
    };
  }

  /** Clicks the checkbox; the app saves, then re-renders it, so wait on the state rather than assuming it. */
  async toggleDone(title) {
    await this.task(title).done.click();
  }

  async addTask(title) {
    await this.newTask.fill(title);
    await this.addButton.click();
    await this.task(title).item.waitFor();
  }
}
